# Generates the color-scheme block at the top of public/assets/styles.css.
# Run: python3 tools/schemes.py   (rewrites everything above the "/* ---- components ---- */" marker)
import pathlib
KEYS = 'bg surface ink muted line paper outline shadow primary on-primary accent on-accent good mid warn bad chalk stitch bill bill2 bill3 gold gold2 gold3 sky sky2 stand1 stand2 wall wall2 grass grass2 clay night'.split()
S = {
 'stadium': {
  'day':   '#CFEAFF #FFFFFF #10233F #4C6283 #A9C6E3 #FFFFFF #10233F #10233F #D7263D #FFFFFF #FFC531 #10233F #2E9E4F #E8A600 #E5671B #C81D32 #FFFFFF #D7263D #4E9A55 #8CC584 #2F6B3A #FFC531 #C98A00 #FFE58A #7CC6F6 #A8DBFA #2B4C7E #3D6BA8 #1F5D3A #143F27 #4FAE4E #3F9A42 #C9804F 0',
  'night': '#071226 #0F2142 #EAF2FF #93A8CC #24406E #12274D #3A5C99 #000000 #FF4458 #FFFFFF #FFB627 #071226 #43D17A #FFC94A #FF8A3D #FF5266 #F4F7FF #FF4458 #4CAF5A #8FD08A #2A6E37 #FFB627 #B97A00 #FFE08A #0B1A3A #142A55 #1C2F55 #2A4377 #123A26 #0A2617 #2F8A3F #277A36 #9C5B33 1'},
 'greenback': {
  'day':   '#DCE8D2 #F7FBF3 #0F2A1A #4D6B57 #B5CCAA #FBFDF7 #0F2A1A #0F2A1A #2F6B3F #FFFFFF #E3B23C #0F2A1A #2F8F4E #C9961B #D4691E #B8352A #FFFFFF #C2352B #5B9E5F #A6D19B #2F6B3F #E3B23C #A87A12 #F7DD8A #CFEBD2 #E4F4E3 #2F6B3F #4E8A57 #2F6B3F #1E4A2A #6DB56A #5CA35A #B8895A 0',
  'night': '#0B1A11 #122A1C #E7F3E9 #93B59C #234A31 #153222 #3C7350 #000000 #6BCB77 #0B1A11 #F2C14E #0B1A11 #6BCB77 #F2C14E #F28A4A #F06A5F #F2F7F2 #F06A5F #4FA25B #8FD08A #2B6B38 #F2C14E #A97E14 #FFE6A0 #0A1F14 #12301F #183A26 #24553A #0E2B1B #071A10 #2C7A3C #246C34 #7E5A35 1'},
 'scoreboard': {
  'day':   '#D5D8DD #F4F5F7 #1B1F24 #5B636E #B7BCC4 #FAFAFB #1B1F24 #1B1F24 #1F5135 #FFFFFF #F6A400 #1B1F24 #2E8B57 #E0A100 #E06A1E #D2382D #FFFFFF #D2382D #4E9A55 #8CC584 #2F6B3A #F6A400 #B07400 #FFD877 #9FB4C7 #BFCDDA #3B4652 #55626F #1F5135 #143824 #4C9A4A #3E8740 #B87A4B 0',
  'night': '#0D1712 #15241B #F2F2E6 #A3AE9F #2A3D31 #1A2C21 #4B6655 #000000 #FFB000 #0D1712 #FFB000 #0D1712 #6EDC8C #FFD24A #FF8A3D #FF5A4F #F2F2E6 #FF5A4F #4FA25B #8FD08A #2B6B38 #FFB000 #A86F00 #FFE08A #050A08 #0E1A13 #17251D #22362A #0F2A1C #081A10 #2A6E37 #225F2F #6E4A2C 1'},
}
def block(sel, vals, dark):
    v = vals.split(); assert len(v) == len(KEYS), (sel, len(v))
    body = '; '.join(f'--{k}:{x}' for k, x in zip(KEYS, v))
    return f'{sel}{{ {body};{" color-scheme:dark;" if dark else ""} }}'
out = ['/* Color schemes (generated by tools/schemes.py). Stadium is the default; each scheme has a day and a night look. */']
out.append(block(':root', S['stadium']['day'], False))
for n in ('greenback', 'scoreboard'): out.append(block(f':root[data-scheme="{n}"]', S[n]['day'], False))
out.append('@media (prefers-color-scheme: dark){')
out.append('  ' + block(':root:not([data-theme="light"])', S['stadium']['night'], True))
for n in ('greenback', 'scoreboard'): out.append('  ' + block(f':root[data-scheme="{n}"]:not([data-theme="light"])', S[n]['night'], True))
out.append('}')
out.append(block(':root[data-theme="dark"]', S['stadium']['night'], True))
for n in ('greenback', 'scoreboard'): out.append(block(f':root[data-scheme="{n}"][data-theme="dark"]', S[n]['night'], True))
p = pathlib.Path(__file__).resolve().parent.parent / 'public/assets/styles.css'
rest = p.read_text().split('/* ---- components ---- */', 1)[1] if p.exists() and '/* ---- components ---- */' in p.read_text() else ''
p.write_text('\n'.join(out) + '\n\n/* ---- components ---- */' + rest)
print('wrote', p)
